import {
  AdditionalDataRegistry,
  instance as additionalDataRegistryInstance,
} from './AdditionalDataRegistry';
import AdditionalData from './AdditionalData';
import EntityRegistry from '@civ-clone/core-registry/EntityRegistry';
import { IConstructor } from '@civ-clone/core-registry/Registry';
import generateInheritance from './lib/generateInheritance';

export type DataObjectFilter = (object: DataObject) => any;

export type PlainObject = {
  [key: string | symbol | number]: any;
};

export type ObjectStore = {
  [key: string]: PlainObject;
};

export type ObjectMap = {
  hierarchy: PlainObject;
  objects: ObjectStore;
};

/**
 * `IConstructor<T>` must stay assignable to `typeof T`.
 *
 * `ConstructorRegistry<T>` hands out `IConstructor<T>`, and the codebase
 * annotates the classes it gets back as `typeof X` —
 * `core-science/PlayerResearch.available()` and
 * `core-government/PlayerGovernment.available()` both do. `IConstructor` is
 * `new (...args: any[]) => T` and carries no statics, so it satisfies
 * `typeof X` only while `X` declares no *required* static.
 *
 * 0.1.14 declared `static readonly transient: readonly string[]` and broke
 * that, which is why it is optional. Nothing failed in this package — its own
 * tests pass either way — and 22 of the 83 checkouts stopped typechecking,
 * from those two call sites. Hence a compile-time assertion rather than a test:
 * the damage was never visible from in here.
 */
type Assert<T extends true> = T;

type ConstructorStaysAssignable = Assert<
  IConstructor<DataObject> extends typeof DataObject ? true : false
>;

/**
 * `type` when a class declares one, its name otherwise.
 *
 * A free function rather than `static typeName()` on `DataObject`, and the
 * reason is worth keeping: the static version was written first, and
 * `ConstructorStaysAssignable` below rejected it on the spot. A required
 * static — method or property — stops `IConstructor<T>` satisfying `typeof T`,
 * which is precisely what 0.1.14 shipped and what broke 22 checkouts. The
 * guard turned a second instance of that into a compile error in the same
 * minute it was written.
 */
export const typeNameOf = (Class: { type?: string; name: string }): string =>
  // `hasOwnProperty`, not `Class.type` — `static` members are inherited, so a
  // subclass of a tagged class reads its *parent's* tag. Every descendant of
  // one tagged class would then save and load as that parent: an entity type
  // quietly swallowing a hierarchy, and ids to match, since `idProvider` keys
  // on this. The same trap `allTransient()` walks the prototype chain to avoid.
  Object.prototype.hasOwnProperty.call(Class, 'type') && Class.type
    ? Class.type
    : Class.name;

/**
 * The per-class id counters, for a save to carry.
 *
 * `DataObject` ids are `<type>-<counter in base 36>`, and the counter is module
 * state. Without restoring it, the first entity created after a load takes an
 * id that a loaded entity already holds — `City-1` twice, one of them
 * unreachable through `getById`. Nothing throws; the second city simply wins
 * some lookups and loses others.
 *
 * Returned as a copy, so a caller holding the result cannot move the engine's
 * counters by mutating it.
 */
export const idCounters = (): Record<string, number> =>
  Object.fromEntries(
    Object.entries(idCache).map(([type, count]) => [type, Number(count)])
  );

/**
 * Restore counters saved by `idCounters()`.
 *
 * Counters only ever move forward: `Math.max` against what is already there,
 * because plugin imports create entities (terrain definitions, civilisations,
 * leaders) *before* a save is loaded, and lowering a counter to the saved value
 * would then hand out ids those definitions already took.
 */
export const restoreIdCounters = (counters: Record<string, number>): void =>
  Object.entries(counters).forEach(([type, count]) => {
    idCache[type] = Math.max(Number(idCache[type] ?? 0), count);
  });

export interface IDataObject {
  addKey(...keys: (string | number | symbol)[]): void;
  allTransient(): readonly string[];
  id(): string;
  stateKeys(): string[];
  keys(): (string | number | symbol)[];
  sourceClass(): IConstructor<this>;
  toPlainObject(): PlainObject;
}

const idCache: { [key: string]: number | bigint } = {},
  idProvider = (object: DataObject) => {
    // `typeName()` rather than `.name`, so ids follow an explicit `type` tag
    // wherever one is declared. Identical today, because nothing declares one
    // yet — which is what makes this change safe to land on its own.
    const className = typeNameOf(object.sourceClass<typeof DataObject>()),
      current = idCache[className];

    if (!current) {
      idCache[className] = 0;
    }

    if (current >= Number.MAX_SAFE_INTEGER) {
      idCache[className] = BigInt(current);
    }

    return className + '-' + (++idCache[className]).toString(36);
  },
  toPlainObject = (
    value: any,
    objects: ObjectStore,
    filter: (object: any) => any = (object) => object,
    additionalDataRegistry: AdditionalDataRegistry = additionalDataRegistryInstance
  ): PlainObject | PlainObject[] => {
    value = filter(value);

    if (value instanceof EntityRegistry) {
      value = value.entries();
    }

    if (Array.isArray(value)) {
      return value.map(
        (item: any): PlainObject =>
          toPlainObject(item, objects, filter, additionalDataRegistry)
      );
    }

    if (value instanceof DataObject) {
      const id = value.id();

      if (!(id in objects)) {
        const plainObject: PlainObject = {
          _: value.sourceClass().name,
          __: generateInheritance(value),
        };

        objects[id] = plainObject;

        // By name, as `keys()` gives them: TypeScript 5 types `value` as a DataObject here, which has no string index.
        const members = value as unknown as Record<string, any>;

        value.keys().forEach((key: string): void => {
          const keyValue: any =
            members[key] instanceof Function ? members[key]() : members[key];

          plainObject[key] = toPlainObject(
            keyValue,
            objects,
            filter,
            additionalDataRegistry
          );
        });

        additionalDataRegistry
          .getByType(value.sourceClass())
          .forEach((additionalData: AdditionalData): void => {
            plainObject[additionalData.key()] = toPlainObject(
              additionalData.data(value),
              objects,
              filter,
              additionalDataRegistry
            );
          });
      }

      return {
        '#ref': id,
      };
    }

    if (value instanceof Function) {
      return {
        _: value.name,
        __: generateInheritance(value),
      };
    }

    if (value && value instanceof Object) {
      return Object.entries(value).reduce(
        (object: PlainObject, [key, value]) => {
          object[key] = toPlainObject(
            value,
            objects,
            filter,
            additionalDataRegistry
          );

          return object;
        },
        {}
      );
    }

    return value;
  };

export class DataObject implements IDataObject {
  /**
   * The name this class is saved and identified under.
   *
   * Optional, and defaulting to `constructor.name` through `typeName()` — see
   * `02-design-review.md` §7, which recommends an explicit tag on every class
   * because the whole identity scheme (entity types, ids, the inheritance
   * chain, the renderer's translation keys) currently rests on one line in
   * `esbuild.js`: `keepNames: true`. Drop it, change bundler, or meet a
   * minifier that handles it differently, and every type silently becomes `t`,
   * `n` or `e`.
   *
   * That rollout is 303 classes across 243 packages, so it is not a
   * prerequisite for saving. What *is* a prerequisite is that mangling cannot
   * corrupt a save quietly, and `ClassRegistry` handles that by refusing a
   * name that looks mangled at registration — loudly, at startup, rather than
   * in a file someone loads next week.
   *
   * Declared optional for the reason 0.1.14 taught: a *required* static stops
   * `IConstructor<T>` satisfying `typeof T`, which broke 22 checkouts.
   */
  static readonly type?: string;

  /**
   * Field names this class does not want saved.
   *
   * **Opt-out, not opt-in.** A field added later is saved by default, so
   * forgetting to declare it wastes bytes; the reverse would lose data
   * silently, and a save format that quietly drops a new field is worse than
   * one that carries a few it did not need.
   *
   * What belongs here is anything the loading game supplies rather than the
   * file: registries, the engine, the generator. Since every constructor in
   * the engine already takes those as parameters, and a `Game` holds them, a
   * transient field is not a hole in the save — it is a field with a different
   * source.
   *
   * Caches belong here too, for a different reason: they are derived, so
   * restoring them would restore a stale answer.
   */
  static readonly transient?: readonly string[] = ['_id', '_keys'];

  private _id: string;
  // `string[]`, not `(keyof this)[]`: `this` widens with each subclass's members, so a field typed by it made no
  //  subclass assignable to its base (civ-clone/web-renderer#21). `addKey` still checks the names it's given.
  private _keys: string[] = ['id'];

  constructor() {
    this._id = idProvider(this);
  }

  addKey(...keys: (keyof this)[]): void {
    this._keys.push(...(keys as string[]));
  }

  id(): string {
    return this._id;
  }

  // Generic on `this` rather than typed by `this`, for the same reason as `_keys`: each caller still gets its own
  //  class's names.
  keys<T extends DataObject>(this: T): (keyof T)[] {
    return (this as DataObject)._keys as (keyof T)[];
  }

  sourceClass<T extends NewableFunction>(): T {
    return this.constructor as T;
  }

  /**
   * Every transient name for this class, including those its ancestors declare.
   *
   * `static` members are inherited, so a subclass declaring its own `transient`
   * *replaces* the parent's rather than adding to it — which would silently
   * start saving `_id` and `_keys` again. Walking the prototype chain is what
   * makes the declarations additive.
   */
  allTransient(): readonly string[] {
    const names = new Set<string>();

    let current: unknown = this.constructor;

    while (typeof current === 'function' && current !== Function.prototype) {
      const declared = (current as { transient?: readonly string[] }).transient;

      if (Array.isArray(declared)) {
        declared.forEach((name) => names.add(name));
      }

      current = Object.getPrototypeOf(current);
    }

    return [...names].sort();
  }

  /**
   * The field names that *would* be saved: own enumerable properties, minus
   * everything transient.
   *
   * This is the whole reason the `#private` → `private` migration happened.
   * With `#private` fields there was nothing to enumerate, so no generic
   * serialiser was possible at all.
   */
  stateKeys(): string[] {
    const transient = new Set(this.allTransient());

    return Object.keys(this)
      .filter((name) => !transient.has(name))
      .sort();
  }

  toPlainObject(
    dataObjectFilter: DataObjectFilter = (object) => object,
    additionalDataRegistry: AdditionalDataRegistry = additionalDataRegistryInstance
  ): ObjectMap {
    const objects = {};

    return {
      hierarchy: toPlainObject(
        this,
        objects,
        dataObjectFilter,
        additionalDataRegistry
      ),
      objects,
    };
  }
}

/**
 * A subclass that adds a member stays assignable to `DataObject`
 * (civ-clone/web-renderer#21). `_keys` and `keys()` were once typed by `this`,
 * which widens with every member a subclass adds, so no such subclass was
 * assignable to its base. As with `ConstructorStaysAssignable`, it's a
 * compile-time assertion: `npm test` doesn't type-check, and `ts:compile`
 * leaves out the tests. `declare`, so nothing is emitted for it.
 */
declare class AddsAMember extends DataObject {
  added(): void;
}

type SubclassStaysAssignable = Assert<
  AddsAMember extends DataObject ? true : false
>;

export default DataObject;
