import {
  AvailableGovernmentRegistry,
  instance as availableGovernmentRegistryInstance,
} from './AvailableGovernmentRegistry';
import {
  DataObject,
  IDataObject,
} from '@civ-clone/core-data-object/DataObject';
import {
  RuleRegistry,
  instance as rulesRegistryInstance,
} from '@civ-clone/core-rule/RuleRegistry';
import Availability from './Rules/Availability';
import Changed from './Rules/Changed';
import Government from './Government';
import Player from '@civ-clone/core-player/Player';

export interface IPlayerGovernment extends IDataObject {
  available(): typeof Government[];
  current(): Government | null;
  is(...governments: typeof Government[]): boolean;
  player(): Player;
  set(government: Government): void;
}

export class PlayerGovernment extends DataObject implements IPlayerGovernment {
  static readonly transient = [
    '_availableGovernmentRegistry',
    '_rulesRegistry',
  ];
  private _availableGovernmentRegistry: AvailableGovernmentRegistry;
  private _government: Government | null = null;
  private _player: Player;
  private _rulesRegistry: RuleRegistry;

  constructor(
    player: Player,
    availableGovernmentRegistry: AvailableGovernmentRegistry = availableGovernmentRegistryInstance,
    rulesRegistry: RuleRegistry = rulesRegistryInstance
  ) {
    super();

    this._player = player;
    this._availableGovernmentRegistry = availableGovernmentRegistry;
    this._rulesRegistry = rulesRegistry;

    this.addKey('available', 'current');
  }

  available(): typeof Government[] {
    return this._availableGovernmentRegistry.filter(
      (GovernmentType: typeof Government) =>
        this._rulesRegistry
          .get(Availability)
          .some((rule) => rule.validate(GovernmentType, this._player))
    );
  }

  current(): Government | null {
    return this._government;
  }

  is(...governments: typeof Government[]): boolean {
    return governments.some(
      (Government) => this._government instanceof Government
    );
  }

  player(): Player {
    return this._player;
  }

  set(government: Government): void {
    this._government = government;

    this._rulesRegistry.process(Changed, this._player, government);
  }
}

export default PlayerGovernment;
