import {
  ApolloProgram,
  Colossus,
  CopernicusObservatory,
  CureForCancer,
  DarwinsVoyage,
  GreatLibrary,
  GreatWall,
  HangingGardens,
  HooverDam,
  IsaacNewtonsCollege,
  JsBachsCathedral,
  Lighthouse,
  MagellansExpedition,
  ManhattanProject,
  MichelangelosChapel,
  Oracle,
  Pyramids,
  SetiProgram,
  ShakespearesTheatre,
  UnitedNations,
  WomensSuffrage,
} from './Wonders';
import {
  Astronomy,
  Automobile,
  BronzeWorking,
  Communism,
  Computers,
  Electricity,
  Electronics,
  GeneticEngineering,
  Gunpowder,
  Industrialization,
  Invention,
  Literacy,
  Magnetism,
  MapMaking,
  Masonry,
  Medicine,
  Mysticism,
  Navigation,
  NuclearFission,
  Pottery,
  Railroad,
  Religion,
  SpaceFlight,
  TheoryOfGravity,
  University,
} from '@civ-clone/civ1-science/Advances';
import {
  HydroPlant,
  NuclearPlant,
  PowerPlant,
} from '@civ-clone/civ1-city-improvement/CityImprovements';
import { Requirement, table } from '@civ-clone/core-requirement/Requirement';
import { HOOVER_DAM_PLANT_RULE_PREFIX } from './RuleIds';
import { Nuclear } from '@civ-clone/civ1-unit/Units';

// What Civilization's Wonders need, what makes them obsolete, and the units they make buildable, as the entries
//  `Rules/City/build` and `Rules/Player/research-complete` make their rules from (civ-clone/web-renderer#37).
//  `registerRules` adds them to the game's `requirements`, where `isObsolete` reads them.

/** The advance a city's player needs before it can build each Wonder: one rule each. */
export const requiresAdvance: Requirement[] = table(
  'civ1-wonder:city/build/requires-advance',
  'requires',
  [
    [Colossus, BronzeWorking],
    [CopernicusObservatory, Astronomy],
    [GreatLibrary, Literacy],
    [GreatWall, Masonry],
    [HangingGardens, Pottery],
    [Lighthouse, MapMaking],
    [MagellansExpedition, Navigation],
    [Oracle, Mysticism],
    [Pyramids, Masonry],
    [ApolloProgram, SpaceFlight],
    [CureForCancer, GeneticEngineering],
    [DarwinsVoyage, Railroad],
    [HooverDam, Electronics],
    [IsaacNewtonsCollege, TheoryOfGravity],
    [JsBachsCathedral, Religion],
    [ManhattanProject, NuclearFission],
    [MichelangelosChapel, Religion],
    [SetiProgram, Computers],
    [ShakespearesTheatre, Medicine],
    [UnitedNations, Communism],
    [WomensSuffrage, Industrialization],
  ]
);

/**
 * Nuclear units need the Manhattan Project, built by anyone in the world (civ-clone/web-renderer#129): one rule. Having
 * built it is enough: it counts even once lost with its city (civ-clone/web-renderer#971).
 */
export const requiresWonder: Requirement[] = table(
  'civ1-wonder:city/build/requires-wonder',
  'requires',
  [[Nuclear, ManhattanProject]],
  { range: 'world' }
);

/**
 * The advance that makes each Wonder obsolete, once *anyone* has discovered it, not just its owner: one rule each, which
 * announces it the first time. `isObsolete` reads these.
 */
export const obsoletedBy: Requirement[] = table(
  'civ1-wonder:wonder/obsolete',
  'obsoletedBy',
  [
    [Colossus, Electricity],
    [CopernicusObservatory, Automobile],
    [GreatLibrary, University],
    [GreatWall, Gunpowder],
    [HangingGardens, Invention],
    [IsaacNewtonsCollege, NuclearFission],
    [Lighthouse, Magnetism],
    [MichelangelosChapel, Communism],
    [Oracle, Religion],
    [Pyramids, Communism],
    [ShakespearesTheatre, Electronics],
  ],
  { range: 'world' }
);

/** The Oracle calms twice as many citizens once its owner has Mysticism. Only describes: `Rules/City/cost` plays it. */
export const enhancedBy: Requirement[] = table(
  'civ1-wonder:wonder/enhanced-by',
  'enhancedBy',
  [[Oracle, Mysticism]]
);

/**
 * A city the Hoover Dam powers isn't offered a plant (`Rules/City/build`'s `hooverDamPlantRules`). Those rules are
 * written by hand, as whether the dam powers a city depends on its owner and continent; these entries name them, under
 * their ids, so the civilopedia, and whatever asks what a Wonder excludes, can find them (civ-clone/web-renderer#965).
 * They only describe: no rule is made from them.
 */
export const hooverDamPlants: Requirement[] = table(
  HOOVER_DAM_PLANT_RULE_PREFIX,
  'excludedBy',
  [
    [PowerPlant, HooverDam],
    [HydroPlant, HooverDam],
    [NuclearPlant, HooverDam],
  ]
);

/** The entries that only describe: no rule is made from them. */
export const describedRequirements: Requirement[] = [...hooverDamPlants];

/** The entries `Rules/City/build`'s deriver makes rules from, in the order the rules were always registered. */
export const buildRequirements: Requirement[] = [
  ...requiresAdvance,
  ...requiresWonder,
];

export default buildRequirements;
