import {
  CityGrowthRegistry,
  instance as cityGrowthRegistryInstance,
} from '@civ-clone/core-city-growth/CityGrowthRegistry';
import {
  CityRegistry,
  instance as cityRegistryInstance,
} from '@civ-clone/core-city/CityRegistry';
import {
  Engine,
  instance as engineInstance,
} from '@civ-clone/core-engine/Engine';
import { Attack } from '@civ-clone/civ1-unit/Actions';
import Criterion from '@civ-clone/core-rule/Criterion';
import Defeated from '@civ-clone/core-unit/Rules/Defeated';
import Effect from '@civ-clone/core-rule/Effect';
import defendersLosing from '../../lib/defendersLosing';

export const getRules: (
  cityRegistry?: CityRegistry,
  cityGrowthRegistry?: CityGrowthRegistry,
  engine?: Engine
) => Defeated[] = (
  cityRegistry: CityRegistry = cityRegistryInstance,
  cityGrowthRegistry: CityGrowthRegistry = cityGrowthRegistryInstance,
  engine: Engine = engineInstance
): Defeated[] => [
  new Defeated(
    'civ1-city:unit/defeated/shrink-defended-city',
    new Criterion(
      (defeated, by, action) =>
        action instanceof Attack &&
        action.to() === defeated.tile() &&
        cityRegistry.getByTile(action.to()) !== null
    ),
    new Effect((defeated, by, action) => {
      const city = cityRegistry.getByTile(defeated.tile())!,
        cityGrowth = cityGrowthRegistry.getByCity(city);

      // Left to the attacker's win, should the city go (civ-clone/web-renderer#969).
      defendersLosing.add(defeated);

      try {
        cityGrowth.shrink(action);
      } finally {
        defendersLosing.delete(defeated);
      }
    })
  ),
  new Defeated(
    'civ1-city:unit/defeated/emit',
    new Effect((defeated, by, action) =>
      engine.emit('unit:defeated', defeated, by, action)
    )
  ),
];

export default getRules;
