import {
  RuleRegistry,
  instance as ruleRegistryInstance,
} from '@civ-clone/core-rule/RuleRegistry';
import { instance as busyRegistryInstance } from '@civ-clone/core-unit/BusyRegistry';
import Action from '@civ-clone/core-unit/Action';
import { ITransport } from '@civ-clone/core-unit-transport/Transport';
import Move from '@civ-clone/base-unit-action-move/Move';
import Moved from '@civ-clone/core-unit/Rules/Moved';
import Stowed from '@civ-clone/base-unit-action-embark/Busy/Stowed';
import Tile from '@civ-clone/core-world/Tile';
import Unit from '@civ-clone/core-unit/Unit';

/**
 * Moves an aircraft onto a `Tile` where it can land, and ends its turn.
 *
 * With a `transport` (a Carrier, say), the aircraft is stowed aboard it and
 * marked `Stowed`, as `Embark` does for a unit boarding a ship. Without one (a
 * city, say), it just lands: nothing needs stowing.
 */
export class LandAircraft extends Move {
  private _transport: ITransport | null;

  constructor(
    from: Tile,
    to: Tile,
    unit: Unit,
    transport: ITransport | null = null,
    ruleRegistry: RuleRegistry = ruleRegistryInstance
  ) {
    super(from, to, unit, ruleRegistry);

    this._transport = transport;
  }

  forUnit(unit: Unit): Action {
    return new LandAircraft(
      this.from(),
      this.to(),
      unit,
      this._transport,
      this.ruleRegistry()
    ) as Action;
  }

  perform(): boolean {
    if (!super.perform()) {
      return false;
    }

    if (this._transport !== null) {
      this._transport.stow(this.unit(), this.from());

      this.unit().setBusy(new Stowed());
    }

    // Landing ends the aircraft's turn.
    this.unit().moves().set(0);
    this.unit().setActive(false);

    // Again, as `Embark` does, so `Moved` rules see the aircraft landed.
    this.ruleRegistry().process(Moved, this.unit(), this as Action);

    return true;
  }

  transport(): ITransport | null {
    return this._transport;
  }
}

// `Stowed` is `Embark`'s, and `Embark` registers how to rebuild it when a save
// loads. Registering it here too (a `Map` set, so it is harmless to repeat)
// means an aircraft saved aboard a Carrier still loads when `Embark` itself
// is never imported.
busyRegistryInstance.register(Stowed, () => new Stowed());

export default LandAircraft;
