// What the UI asks the worker for (#449), moved out of `DataTransferClient`: the Top Cities, Wonders (#992) and
//  intelligence reports, the Civilization Score and the sidebar's Power list (#701, #708), what a city can and can't build and a unit's actions, each
//  answered on the channel it was asked on.
//  The client's `topCities` and `civilizationScore` are two of these: `topCities` for its test (`topCities.ts`), and
//  `civilizationScore` for the ending window (`gameEnd.ts`).

import Player from '@civ-clone/core-player/Player';
import Tile from '@civ-clone/core-world/Tile';
import CityBuildItem from '@civ-clone/core-city-build/CityBuild';
import { ObjectMap } from '@civ-clone/core-data-object/DataObject';
import Transport, {
  TransportDisposer,
} from '@civ-clone/core-data-client/Transport';
import {
  defaultTopCitiesLimit,
  topCitiesEntries,
  topCitiesRows,
} from '../lib/topCities';
import {
  TopCitiesRow,
  CivilizationScore,
  CivilizationPowerRow,
  WondersRow,
} from '@civ-clone/ui-protocol/reports';
import { builtWonders, wondersEntries, wondersRows } from '../lib/wonders';
import { civilizationScore as civilizationScoreOf } from '../lib/civilizationScore';
import { civilizationPowerRows } from '../lib/civilizationPower';
import { ClientContext, Registries } from './ClientContext';
import { DataFilter, serialiseUnit } from './visibilityFilter';
import { intelligenceRows } from '../lib/intelligence';
import { militaryReport } from '../lib/military';
import { buildListDetails, inBuildListOrder } from '../lib/buildList';
import { RuleRegistry } from '@civ-clone/core-rule/RuleRegistry';
import { unavailableBuildItems } from '../lib/civilopedia';
import { standalone } from './refs';
import answer from '../answer';

export type RequestsContext = Pick<
  ClientContext,
  | 'player'
  // Which players are our own.
  | 'view'
  // Whether the view has met a player and seen a square, which say what the reports may show of them.
  | 'hasMet'
  | 'hasSeen'
  // What the player may see, which a city's build list and a unit's actions go through.
  | 'dataFilter'
  // The unit the UI has the actions of (#323), which `unitActions` changes.
  | 'actions'
  | 'patches'
  // Each handed whole to the Top Cities report, the Wonders report or the Civilization Score.
  | 'cities'
  | 'cityGrowths'
  | 'gameResults'
  // Every civilization still in the game, for the sidebar's Power list (#701, #708).
  | 'players'
  | 'playerWorlds'
  | 'rules'
  | 'specialists'
  | 'wonders'
  // The Military report's (#405).
  | 'availableCityBuildItems'
  // Every Wonder ever built, standing or lost, for the Wonders report (#971, #992).
  | 'cityImprovements'
> &
  Registries<{
    cities: 'getByPlayer';
    cityBuilds: 'getBy';
    unitLosses: 'getByPlayer';
    units: 'getBy' | 'getByPlayer';
  }>;

export const topCities = (
  ctx: RequestsContext,
  limit: number = defaultTopCitiesLimit
): TopCitiesRow[] =>
  topCitiesRows(
    topCitiesEntries(ctx.player(), {
      cities: ctx.cities,
      cityGrowths: ctx.cityGrowths,
      specialists: ctx.specialists,
      wonders: ctx.wonders,
      hasSeen: (tile: Tile) => ctx.hasSeen(tile),
      hasMet: (player: Player) => ctx.hasMet(player),
    }),
    Number.isInteger(limit) && limit > 0 ? limit : defaultTopCitiesLimit
  );

// Every Wonder built (#992), standing or lost (#971), in the order the rule set lists them.
export const wonders = (ctx: RequestsContext): WondersRow[] =>
  wondersRows(
    wondersEntries(
      ctx.player(),
      builtWonders({
        wonders: ctx.wonders,
        cityImprovements: ctx.cityImprovements,
      }),
      {
        hasSeen: (tile: Tile) => ctx.hasSeen(tile),
        hasMet: (player: Player) => ctx.hasMet(player),
        owns: (player: Player) => ctx.view.owns(player),
      }
    )
  );

export const civilizationScore = (ctx: RequestsContext): CivilizationScore =>
  civilizationScoreOf(ctx.player(), {
    gameResults: ctx.gameResults,
    playerWorlds: ctx.playerWorlds,
    rules: ctx.rules,
  });

export const civilizationPower = (
  ctx: RequestsContext
): CivilizationPowerRow[] =>
  civilizationPowerRows(ctx.player(), {
    players: ctx.players,
    rules: ctx.rules,
    hasMet: (player: Player) => ctx.hasMet(player),
    // An observer's view owns its group, or nobody (#607).
    owns: (player: Player) => ctx.view.owns(player),
  });

export const cityBuildAvailable = (
  dataFilter: DataFilter,
  cityBuild: CityBuildItem,
  rules: RuleRegistry
): ObjectMap => {
  // By section, for the picker's headings (#432).
  const available = inBuildListOrder(cityBuild.available(), (buildItem) =>
      buildItem.item()
    ),
    filter = dataFilter(standalone);

  // `toPlainObject` is a method on `DataObject`, and it is the only way in: the filter is applied to what it is called
  //  on first, so handing it the list in place of the build gets the list serialised, as the `hierarchy`.
  const objectMap = cityBuild.toPlainObject((object: any) =>
    object === cityBuild ? available : filter(object)
  );

  // Each item's section and a unit's numbers (#381), and the ids of the rules that would hold it in this city as it is
  //  now (#970), so the list can say an item would wait before it is chosen. Added here rather than as
  //  `AdditionalData` on `BuildItem`, which would add them to the `building` in every `CityBuild` patch too.
  available.forEach((buildItem) => {
    const plainObject = objectMap.objects[buildItem.id()];

    if (plainObject) {
      Object.assign(plainObject, buildListDetails(buildItem.item(), rules), {
        held: cityBuild.heldFor(buildItem.item()),
      });
    }
  });

  return objectMap;
};

export const registerRequests = (
  transport: Transport<TransportDataMap>,
  ctx: RequestsContext
): TransportDisposer => {
  const disposers: TransportDisposer[] = [];

  // Worked out here and sent as finished rows, so the UI learns nothing about rival cities beyond what the report
  //  shows (#124).
  disposers.push(
    answer(transport, 'topCities', (limit) => topCities(ctx, limit))
  );

  // The Wonders of the World (F7, #992), worked out here for the same reason.
  disposers.push(answer(transport, 'wonders', () => wonders(ctx)));

  // The engine's `Score` rules add it up (#149).
  disposers.push(
    answer(transport, 'civilizationScore', () => civilizationScore(ctx))
  );

  // And everyone's, ranked, for the sidebar (#701): an unmet civilization's row says nothing of who it is.
  disposers.push(
    answer(transport, 'civilizationPower', () => civilizationPower(ctx))
  );

  // Each request is answered with `answer`, so one that throws is answered with a `requestFailed` rather than never, and
  //  the UI hears that it failed, rather than waiting for good (#470).

  // What a city can build, for the production picker (#324). Standalone, as a notification is, so the picker's list
  //  resolves on its own and brings nothing of the game with it. A build that is not ours has nothing to show.
  disposers.push(
    answer(transport, 'cityBuildAvailable', (cityBuildId) => {
      const [cityBuild] = ctx.cityBuilds.getBy('id', cityBuildId);

      return cityBuild && ctx.view.owns(cityBuild.city().player())
        ? cityBuildAvailable(ctx.dataFilter, cityBuild, ctx.rules)
        : { hierarchy: [], objects: {} };
    })
  );

  // Why a city can't build each item, for the build list's Can't build window (#183). The local player's own cities
  //  only, like `cityBuildAvailable`.
  disposers.push(
    answer(transport, 'cityBuildUnavailable', (cityBuildId) => {
      const [cityBuild] = ctx.cityBuilds.getBy('id', cityBuildId);

      return cityBuild && cityBuild.city().player() === ctx.player()
        ? unavailableBuildItems(cityBuild)
        : [];
    })
  );

  // The UI makes a unit active and asks for its actions, which the patches leave out for every other unit (#323). The
  //  answer is a patch of that unit alone, with its tiles as refs the UI already holds.
  disposers.push(
    transport.receive('unitActions', (unitId) => {
      const [unit] = ctx.units.getBy('id', unitId);

      if (!unit || !ctx.view.owns(unit.player())) {
        return;
      }

      // When the UI had another unit's actions, that unit goes again without them.
      ctx.actions.setUnitWithActions(unit, (previous) =>
        ctx.patches.unit(previous)
      );

      ctx.patches.update(unit.id(), () => {
        ctx.actions.answering = unit;

        try {
          return serialiseUnit(ctx.dataFilter, unit);
        } finally {
          ctx.actions.answering = null;
        }
      });

      ctx.patches.flush();
    })
  );

  // The intelligence report (F3, #58), worked out here for the same reason as the Top Cities.
  disposers.push(
    answer(transport, 'intelligence', () =>
      intelligenceRows(ctx.player(), (player) => ctx.hasMet(player))
    )
  );

  // The Military report (F2, #405): our own units and losses only.
  disposers.push(
    answer(transport, 'military', () => militaryReport(ctx.player(), ctx))
  );

  return () => disposers.forEach((dispose) => dispose());
};

export default registerRequests;
