import Player from '@civ-clone/core-player/Player';
import Rank from '../Rules/Rank';
import RuleRegistry from '@civ-clone/core-rule/RuleRegistry';

// The player's ranking score: every `Rank` match added together, 0 if none.
export const rank = (player: Player, ruleRegistry: RuleRegistry): number =>
  ruleRegistry
    .process(Rank, player)
    .reduce((total: number, value: number): number => total + value, 0);

// `players` from the highest ranking score to the lowest. A tie goes to the player listed first, so the order is
//  stable for a stable list of players.
export const rankings = (
  players: Player[],
  ruleRegistry: RuleRegistry
): Player[] =>
  players
    .map((player: Player, index: number) => ({
      player,
      index,
      score: rank(player, ruleRegistry),
    }))
    .sort((a, b) => b.score - a.score || a.index - b.index)
    .map(({ player }) => player);

export default rank;
