import Player from '@civ-clone/core-player/Player';
import Rule from '@civ-clone/core-rule/Rule';

// A part of a player's ranking score: its treasury, its citizens, what it knows, its army. Every match is added
//  together (`rank`), so a ruleset lists the terms it counts and another can add its own.
export class Rank extends Rule<[Player], number> {}

export default Rank;
