// Generic: the ship a city should build to explore the sea with, if any (civ-clone/web-renderer#208). A player with
//  more than one city keeps one ship at a time for this, built in a city that has its defenders and is on a sea, not a
//  lake, that leads to water it hasn't explored. Transports and their escorts are another matter.
import { wantsUnit } from './defence';
import BuildItem from '@civ-clone/core-city-build/BuildItem';
import Buildable from '@civ-clone/core-city-build/Buildable';
import City from '@civ-clone/core-city/City';
import Dependencies from '@civ-clone/base-strategy-ai/lib/Dependencies';
import buildTime, { finishesWithin, netShields } from './buildTime';
import Knowledge from '@civ-clone/base-strategy-ai/lib/Knowledge';
import { Naval, NavalTransport } from '@civ-clone/library-unit/Types';
import Memory from '@civ-clone/base-strategy-ai/lib/Memory';
import { canBerthAt, isFerrying, waitingAt } from '../Unit/overseas';
import islandBound from '../Player/islandBound';
import Player from '@civ-clone/core-player/Player';
import { TargetBoard } from '@civ-clone/base-strategy-ai/lib/Memory';
import Tile from '@civ-clone/core-world/Tile';
import Unit from '@civ-clone/core-unit/Unit';

const isShip = (item: object): boolean =>
  Object.prototype.isPrototypeOf.call(Naval, item);

// The water tiles joined to `city`'s by water, found one at a time: from the map itself, or, with `known`, only those
//  tiles. Stops as soon as `enough` returns `true`, or after `limit` tiles.
const searchWater = (
  city: City,
  enough: (tile: Tile, found: number) => boolean,
  known: (tile: Tile) => boolean = (): boolean => true,
  limit: number = 1000
): boolean => {
  const found = new Set<Tile>(),
    queue: Tile[] = [];

  const visit = (tile: Tile): void => {
    if (tile.isWater() && !found.has(tile) && known(tile)) {
      found.add(tile);
      queue.push(tile);
    }
  };

  city.tile().getNeighbours().forEach(visit);

  for (let i = 0; i < queue.length && i < limit; i++) {
    if (enough(queue[i], i + 1)) {
      return true;
    }

    queue[i].getNeighbours().forEach(visit);
  }

  return false;
};

// Whether `city` is on the sea rather than a lake: on a body of water of at least `seaSize` tiles. It's judged from the
//  map, as Civ1's own computer players know the extent of each ocean, and a lake the player has only partly seen
//  looks no different from a sea.
export const isOnSea = (city: City, seaSize: number = 20): boolean =>
  searchWater(city, (tile: Tile, found: number): boolean => found >= seaSize);

// Whether the water beside `city`, as far as the player knows it, reaches a tile on the edge of what it has explored.
export const reachesSeaToExplore = (
  dependencies: Dependencies,
  player: Player,
  targets: TargetBoard,
  city: City
): boolean => {
  const playerWorld = dependencies.playerWorldRegistry.getByPlayer(player),
    toExplore = new Set<Tile>(targets.seaTilesToExplore);

  return (
    toExplore.size > 0 &&
    searchWater(
      city,
      (tile: Tile): boolean => toExplore.has(tile),
      (tile: Tile): boolean => playerWorld.includes(tile)
    )
  );
};

// How many turns, at its net shields, a city spends on a ship to explore with (civ-clone/web-renderer#212).
export const explorerShipTurns = 20;

// The cheapest ship `city` can build, if the player has another city (or is bound to its land), no ship free to explore (one that's ferrying
//  isn't, civ-clone/web-renderer#440) and none on order, the city has its
//  defenders, it's on a sea it can explore, it can finish the ship within `turns`, and it would still have shields to
//  spare once it supported the ship (civ-clone/web-renderer#229). Otherwise `null`. A player's only city has better
//  things to build.
export const explorerShipFor = (
  dependencies: Dependencies,
  player: Player,
  memory: Memory,
  city: City,
  knowledge: Knowledge,
  turns: number = explorerShipTurns
): typeof Buildable | null => {
  const { targets } = memory;

  const [ship] = dependencies.cityBuildRegistry
    .getByCity(city)
    .available()
    .filter((buildItem: BuildItem): boolean => isShip(buildItem.item()))
    .sort(
      (a: BuildItem, b: BuildItem): number =>
        a.cost().value() - b.cost().value()
    );

  if (
    !ship ||
    // A player bound to its land explores from its only city (civ-clone/web-renderer#632): otherwise it never sees
    //  land to settle overseas.
    (dependencies.cityRegistry.getByPlayer(player).length < 2 &&
      !islandBound(dependencies, knowledge, player, memory)) ||
    dependencies.unitRegistry
      .getByPlayer(player)
      .some(
        (unit: Unit): boolean =>
          unit instanceof Naval && !isFerrying(dependencies, memory, unit)
      ) ||
    dependencies.cityRegistry
      .getByPlayer(player)
      .some((other: City): boolean => {
        const building = dependencies.cityBuildRegistry
          .getByCity(other)
          .building();

        return building !== null && isShip(building.item());
      }) ||
    wantsUnit(dependencies, knowledge, city) ||
    netShields(city) - knowledge.unitSupport(dependencies, city) <= 0 ||
    !finishesWithin(buildTime(dependencies, city)(ship), turns) ||
    !isOnSea(city) ||
    !reachesSeaToExplore(dependencies, player, targets, city)
  ) {
    return null;
  }

  return ship.item() as unknown as typeof Buildable;
};

export default explorerShipFor;

// How many turns passengers wait in a port before it builds a transport for them.
export const ferryWait = 2;

// What a transport on order is taken to carry, before it's built and its own capacity is known.
const ORDERED_CAPACITY = 2;

interface Transport {
  capacity(): { value(): number };
  cargo(): Unit[];
}

// The cheapest transport `city` can build for passengers that have waited in it `ferryWait` turns or more
//  (`lib/Unit/overseas`, civ-clone/web-renderer#211), while they outnumber the room on the player's empty transports
//  that could sail alongside it and those on order. One on another sea doesn't count, and for invaders gathering a
//  force, a port builds as many as they need (civ-clone/web-renderer#374). Otherwise `null`.
export const ferryShipFor = (
  dependencies: Dependencies,
  player: Player,
  memory: Memory,
  city: City
): typeof Buildable | null => {
  const turn = dependencies.turn.value(),
    waiting = waitingAt(memory, city).filter(
      ([, passenger]): boolean =>
        passenger.since !== null && turn - passenger.since >= ferryWait
    ),
    isTransport = (item: object): boolean =>
      Object.prototype.isPrototypeOf.call(NavalTransport, item),
    [ship] = dependencies.cityBuildRegistry
      .getByCity(city)
      .available()
      .filter((buildItem: BuildItem): boolean => isTransport(buildItem.item()))
      .sort(
        (a: BuildItem, b: BuildItem): number =>
          a.cost().value() - b.cost().value()
      );

  if (waiting.length === 0 || !ship) {
    return null;
  }

  const room =
    dependencies.unitRegistry
      .getByPlayer(player)
      .filter(
        (unit: Unit): boolean =>
          unit instanceof NavalTransport &&
          (unit as unknown as Transport).cargo().length === 0 &&
          canBerthAt(unit as unknown as Unit, city)
      )
      .reduce(
        (total: number, unit: Unit): number =>
          total + (unit as unknown as Transport).capacity().value(),
        0
      ) +
    ORDERED_CAPACITY *
      dependencies.cityRegistry
        .getByPlayer(player)
        .filter((other: City): boolean => {
          const building = dependencies.cityBuildRegistry
            .getByCity(other)
            .building();

          return building !== null && isTransport(building.item());
        }).length;

  return waiting.length > room
    ? (ship.item() as unknown as typeof Buildable)
    : null;
};
