import MilitaryStrength, { IStrength } from '../Rules/MilitaryStrength';
import RuleRegistry from '@civ-clone/core-rule/RuleRegistry';
import Unit from '@civ-clone/core-unit/Unit';

const add = (a: IStrength, b: IStrength): IStrength => ({
  attack: a.attack + b.attack,
  defence: a.defence + b.defence,
});

const none = (): IStrength => ({ attack: 0, defence: 0 });

// What one unit adds: every `MilitaryStrength` match added together.
export const strength = (unit: Unit, ruleRegistry: RuleRegistry): IStrength =>
  ruleRegistry.process(MilitaryStrength, unit).reduce(add, none());

// The attack and defence of `units` added together. The caller picks the units: a player's, or a player's on one
//  land mass, so this needs no knowledge of where units are.
export const militaryStrength = (
  units: Unit[],
  ruleRegistry: RuleRegistry
): IStrength =>
  units.reduce(
    (total: IStrength, unit: Unit): IStrength =>
      add(total, strength(unit, ruleRegistry)),
    none()
  );

// `militaryStrength` as one number, attack and defence together.
export const militaryPower = (
  units: Unit[],
  ruleRegistry: RuleRegistry
): number => {
  const { attack, defence } = militaryStrength(units, ruleRegistry);

  return attack + defence;
};

export default militaryPower;
