import describedRequirements from './Requirements';
import cityCelebrateLeader from './Rules/City/celebrate-leader';
import cityCelebrationYield from './Rules/City/celebration-yield';
import cityCivilDisorder from './Rules/City/civil-disorder';
import cityCost from './Rules/City/cost';
import cityDestroyed from './Rules/City/destroyed';
import cityYield from './Rules/City/yield';
import playerAction from './Rules/Player/action';
import playerTurnStart from './Rules/Player/turn-start';
import { Game, defaultGame } from '@civ-clone/core-game';

export const register = (game: Game): void => {
  game.rules.register(
    ...cityCelebrateLeader(game.cityGrowth, game.specialists),
    ...cityCelebrationYield(
      game.pendingEffects,
      game.playerGovernments,
      game.tileImprovements
    ),
    ...cityYield(
      game.cityGrowth,
      game.playerGovernments,
      game.units,
      game.cities,
      game.difficulty,
      game.clients
    ),
    ...cityCivilDisorder(game.cityGrowth, game.specialists),
    ...cityCost(
      game.rules,
      game.cityGrowth,
      game.cityImprovements,
      game.playerGovernments,
      game.playerResearch,
      game.units
    ),
    ...cityDestroyed(game.pendingEffects),
    ...playerAction(game.cities, game.pendingEffects),
    ...playerTurnStart(
      game.cities,
      game.rules,
      game.engine,
      game.cityGrowth,
      game.playerGovernments,
      game.pendingEffects,
      game.turn
    )
  );

  // What makes its improvements work better, for the civilopedia: they only describe, so no rules are made from them
  //  (civ-clone/web-renderer#37).
  game.requirements.add(null, ...describedRequirements);
};

// The plugin loader imports each package for this side effect. Until it passes
// a `Game` of its own, dropping it would produce a game with silently absent
// rules — no error, just wrong behaviour.
register(defaultGame);

export default register;
